CREATE SEQUENCE "CYCLE_SEQ" MAXVALUE 5 MINVALUE 1 CACHE 3 CYCLE;

CREATE SEQUENCE "DOWN_SEQ" INCREMENT BY -2 MAXVALUE -1 MINVALUE -100 CACHE 20;

CREATE SEQUENCE "NOCACHE_SEQ" MAXVALUE 9999999999999999999999999999 MINVALUE 1 NOCACHE;

CREATE SEQUENCE "ORDER_SEQ" INCREMENT BY 2 MAXVALUE 9999999999999999999999999999 MINVALUE 1 CACHE 20;

CREATE TABLE "CHILD" (
  "ID" NUMBER NOT NULL,
  "PARENT_ID" NUMBER NOT NULL,
  "QTY" NUMBER DEFAULT 1,
  CONSTRAINT "CHILD_PK" PRIMARY KEY ("ID"),
  CONSTRAINT "CHILD_QTY_CK" CHECK (QTY > 0)
);

CREATE INDEX "CHILD_PARENT_IDX" ON "CHILD" ("PARENT_ID" ASC);

CREATE TABLE "COMPOSITE" (
  "A" NUMBER NOT NULL,
  "B" VARCHAR2(10 BYTE) NOT NULL,
  "C" NUMBER,
  CONSTRAINT "COMPOSITE_C_UK" UNIQUE ("C"),
  CONSTRAINT "COMPOSITE_PK" PRIMARY KEY ("A", "B")
);

CREATE TABLE "DISABLED_PK" (
  "A" NUMBER,
  CONSTRAINT "DISABLED_PK" PRIMARY KEY ("A")
);

CREATE TABLE "HIDDEN_IDX" (
  "ID" NUMBER NOT NULL
);

CREATE INDEX "HIDDEN_IDX_PK_IDX" ON "HIDDEN_IDX" ("ID" ASC) INVISIBLE;

ALTER TABLE "HIDDEN_IDX" ADD CONSTRAINT "HIDDEN_IDX_PK" PRIMARY KEY ("ID") USING INDEX "HIDDEN_IDX_PK_IDX";

CREATE TABLE "IDENT" (
  "ID" NUMBER GENERATED ALWAYS AS IDENTITY (START WITH 1 INCREMENT BY 1) NOT NULL,
  "COMPUTED" NUMBER GENERATED ALWAYS AS ("ID"*2) VIRTUAL,
  "STORED_GENERATED" NUMBER GENERATED ALWAYS AS ("ID"+1) VIRTUAL,
  "HIDDEN" NUMBER INVISIBLE DEFAULT 7,
  CONSTRAINT "IDENT_PK" PRIMARY KEY ("ID")
);

CREATE TABLE "IDENT_DEFAULT" (
  "ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 100 INCREMENT BY 5) NOT NULL,
  "NOTE" VARCHAR2(20 BYTE)
);

CREATE TABLE "NO_CONSTRAINTS" (
  "A" NUMBER,
  "B" VARCHAR2(10 BYTE)
);

CREATE TABLE "PARENT" (
  "ID" NUMBER NOT NULL,
  "NAME" VARCHAR2(40 BYTE) NOT NULL,
  CONSTRAINT "PARENT_NAME_UK" UNIQUE ("NAME"),
  CONSTRAINT "PARENT_PK" PRIMARY KEY ("ID")
);

CREATE OR REPLACE TRIGGER OMNI_APP.PARENT_TRG BEFORE INSERT ON OMNI_APP.PARENT FOR EACH ROW BEGIN NULL; END;

CREATE TABLE "REUSED" (
  "ID" NUMBER NOT NULL,
  "CODE" VARCHAR2(20 BYTE) NOT NULL
);

CREATE INDEX "REUSED_CODE_IDX" ON "REUSED" ("CODE" ASC);

ALTER TABLE "REUSED" ADD CONSTRAINT "REUSED_CODE_UK" UNIQUE ("CODE") USING INDEX "REUSED_CODE_IDX";

CREATE INDEX "REUSED_ID_IDX" ON "REUSED" ("ID" ASC);

ALTER TABLE "REUSED" ADD CONSTRAINT "REUSED_PK" PRIMARY KEY ("ID") USING INDEX "REUSED_ID_IDX";

CREATE TABLE "TYPES" (
  "ID" NUMBER(10) NOT NULL,
  "AMOUNT" NUMBER(12,2) DEFAULT 0 NOT NULL,
  "ROUNDED" NUMBER(5,-2),
  "SCALED" NUMBER(*,2),
  "RATIO" FLOAT(126),
  "LABEL" VARCHAR2(50 CHAR),
  "BYTES" VARCHAR2(50 BYTE),
  "NATIONAL" NVARCHAR2(20),
  "CODE" CHAR(3 BYTE),
  "NOTE" CLOB,
  "BLOB_DATA" BLOB,
  "RAW_DATA" RAW(16),
  "FLAG" NUMBER(1) DEFAULT 0,
  "SEQ_TEXT" VARCHAR2(40 BYTE) DEFAULT '"OMNI_APP"."S".NEXTVAL',
  "CREATED" DATE DEFAULT SYSDATE,
  "AT" TIMESTAMP(3),
  "AT_ZONE" TIMESTAMP(6) WITH TIME ZONE,
  "Mixed Case" NUMBER,
  CONSTRAINT "TYPES_PK" PRIMARY KEY ("ID")
);

COMMENT ON TABLE "TYPES" IS 'types the sync reads';
COMMENT ON COLUMN "TYPES"."LABEL" IS 'a label';
COMMENT ON COLUMN "TYPES"."NOTE" IS 'a note';
COMMENT ON COLUMN "TYPES"."Mixed Case" IS 'a quoted name';
CREATE TABLE "UNNAMED_UK" (
  "A" NUMBER,
  CONSTRAINT "SYS_C9000019" UNIQUE ("A")
);

CREATE TABLE "VIRTUAL_UK" (
  "EMAIL" VARCHAR2(40 BYTE) NOT NULL,
  "UPPER_EMAIL" VARCHAR2(40 BYTE) GENERATED ALWAYS AS (UPPER("EMAIL")) VIRTUAL,
  CONSTRAINT "VIRTUAL_UK_IDX" UNIQUE ("UPPER_EMAIL")
);

ALTER TABLE "CHILD" ADD CONSTRAINT "CHILD_PARENT_FK" FOREIGN KEY ("PARENT_ID") REFERENCES "PARENT" ("ID") ON DELETE CASCADE;

CREATE MATERIALIZED VIEW "PARENT_MV" AS SELECT ID, NAME FROM OMNI_APP.PARENT
;

COMMENT ON MATERIALIZED VIEW "PARENT_MV" IS 'the parents, kept';

CREATE VIEW "PARENT_VIEW" AS SELECT ID, NAME FROM OMNI_APP.PARENT;

COMMENT ON TABLE "PARENT_VIEW" IS 'the parents, without the quantity';

CREATE OR REPLACE PROCEDURE          TOUCH (P_ID IN NUMBER) AS BEGIN NULL; END;

CREATE UNIQUE INDEX "PARENT_UPPER_NAME_IDX" ON "PARENT" (UPPER("NAME") ASC);

